testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

func run() -> Vector3i:
	var pos: Vector3 = Vector3(3.5, 2.0, -5.1)
	var cell: Vector3i = Vector3i(floori(pos.x / 2.0), floori(pos.y / 2.0), floori(pos.z / 2.0))
	return cell
",
   "domanda": "Quali coordinate di cella restituisce `run()`?",
   "spiegazione": "Ogni componente viene divisa per 2.0 e arrotondata con `floori()`: 3.5/2 = 1.75 -> 1; 2.0/2 = 1.0 -> 1; -5.1/2 = -2.55 -> -3 (perché floori arrotonda verso meno infinito)."
  },
  {
   "codice": "extends RefCounted

func run() -> int:
	var default_val: int = -1
	if default_val == GridMap.INVALID_CELL_ITEM:
		return 1
	return 0
",
   "domanda": "Quanto vale il numero restituito da `run()`?",
   "spiegazione": "`GridMap.INVALID_CELL_ITEM` è la costante predefinita che rappresenta una cella vuota, il cui valore numerico è -1. Poiché `default_val` è -1, la condizione è vera e restituisce 1."
  },
  {
   "codice": "extends RefCounted

func run() -> bool:
	var use_collision: bool = true
	var p_z: float = -5.0
	var supported: bool = false
	if use_collision and p_z >= -7.0 and p_z <= -1.0:
		supported = true
	return supported
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "`use_collision` è true e `p_z` (-5.0) si trova nell'intervallo tra -7.0 e -1.0. Tutte le condizioni dell' `if` sono verificate, quindi `supported` diventa `true`."
  },
  {
   "codice": "extends RefCounted

func run() -> int:
	var count: int = 0
	for x in range(-1, 2):
		if x == 0:
			count += 1
	return count
",
   "domanda": "Quanto vale `count` alla fine?",
   "spiegazione": "Il ciclo `range(-1, 2)` produce i valori -1, 0 e 1. La condizione `x == 0` risulta vera solo quando il ciclo esamina lo 0, incrementando `count` una sola volta."
  },
  {
   "codice": "extends RefCounted

func run() -> int:
	return floori(-0.5)
",
   "domanda": "Che numero intero restituisce `floori(-0.5)`?",
   "spiegazione": "`floori()` arrotonda sempre verso il basso (verso meno infinito). Per il numero -0.5, l'intero immediatamente inferiore è -1, non 0."
  }
 ]
}
